/// Shift type from opcode bits 5-6 (ARM) or the THUMB shift opcodes.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ShiftType {
    LogicalLeft,      // LSL
    LogicalRight,     // LSR
    ArithmeticRight,  // ASR
    RotateRight,      // ROR (RRX when the immediate amount is 0)
}

impl ShiftType {
