    pub fn from_bits(bits: u32) -> Self {
        match bits & 3 {
            0 => ShiftType::LogicalLeft,
            1 => ShiftType::LogicalRight,
            2 => ShiftType::ArithmeticRight,
            _ => ShiftType::RotateRight,
        }
    }
}

