/// (gbatek: ARM Opcodes: Data Processing (ALU), "Shift by Register").
pub fn shift_by_register(shift_type: ShiftType, value: u32, register_value: u32, carry_in: bool) -> ShiftResult {
    let amount = register_value & 0xFF;
    if amount == 0 {
